var style=document.createElement('style');style.id='adm-m13-theory-style-offline';style.textContent=".adm-m13-book{--i:var(--text,#e9eef6);--m:var(--muted,#91a3b9);--r:var(--line,#26364f);--p:var(--panel,#0d1727);--p2:var(--panel2,#111d2f);--a:#93abc9;--w:#d7b879;margin:18px 0 8px;border-top:1px solid var(--r);color:var(--i);font-size:14px;line-height:1.72}.adm-m13-book *{box-sizing:border-box}.adm-m13-book p{margin:9px 0}.adm-m13-book b,.adm-m13-book strong{font-weight:800;color:inherit}.adm-m13-cover{padding:28px 0 24px;border-bottom:1px solid var(--r)}.adm-m13-kicker{display:flex;justify-content:space-between;gap:12px;color:var(--m);font-size:9px;font-weight:850;letter-spacing:.12em}.adm-m13-type{margin:20px 0 5px!important;color:var(--w);font-size:10px;font-weight:850;letter-spacing:.1em;text-transform:uppercase}.adm-m13-cover h2{max-width:920px;margin:0;font:650 clamp(25px,4vw,38px)/1.08 Georgia,\"Times New Roman\",serif;letter-spacing:-.025em}.adm-m13-sub{max-width:900px;margin:12px 0 0!important;color:var(--m);font:italic 14px/1.55 Georgia,\"Times New Roman\",serif}.adm-m13-source-note{margin-top:18px;padding-top:13px;border-top:1px solid var(--r);color:var(--m);font-size:10px}.adm-m13-toc{position:sticky;top:8px;z-index:4;margin:14px 0 24px;padding:6px;display:flex;gap:4px;overflow:auto;border:1px solid var(--r);border-radius:10px;background:color-mix(in srgb,var(--p) 94%,transparent);backdrop-filter:blur(10px)}.adm-m13-toc a{display:flex;gap:7px;align-items:center;min-width:max-content;padding:8px 9px;border-radius:7px;color:var(--m)!important;text-decoration:none!important;font-size:10px;font-weight:700}.adm-m13-toc a:hover{background:var(--p2);color:var(--i)!important}.adm-m13-toc b{color:var(--w)}.adm-m13-orientacao{margin:0 0 30px;padding:18px 0 20px;border-bottom:1px solid var(--r)}.adm-m13-orientacao h3,.adm-m13-final h3{margin:0 0 10px;font:650 22px/1.2 Georgia,\"Times New Roman\",serif}.adm-m13-flow{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:13px}.adm-m13-flow span{padding:5px 8px;border:1px solid var(--r);border-radius:999px;font-size:9px;font-weight:800;color:var(--m)}.adm-m13-flow i{color:var(--m);font-style:normal}.adm-m13-session{scroll-margin-top:70px;padding:30px 0;border-bottom:1px solid var(--r)}.adm-m13-session-head{margin-bottom:20px}.adm-m13-session-head small{display:block;margin-bottom:7px;color:var(--w);font-size:9px;font-weight:900;letter-spacing:.14em}.adm-m13-session-head h3{max-width:920px;margin:0;font:650 clamp(22px,3vw,29px)/1.17 Georgia,\"Times New Roman\",serif;letter-spacing:-.015em}.adm-m13-session h3{margin:24px 0 9px;color:var(--a);font-size:11px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.adm-m13-session ul,.adm-m13-session ol,.adm-m13-final ul,.adm-m13-final ol{padding-left:22px}.adm-m13-session li,.adm-m13-final li{margin:6px 0}.adm-m13-callout{margin:16px 0;padding:13px 15px;border-left:3px solid var(--a);background:color-mix(in srgb,var(--p2) 80%,transparent);border-radius:0 8px 8px 0}.adm-m13-callout.exam,.adm-m13-callout.trap{border-left-color:var(--w)}.adm-m13-table-wrap{margin:15px 0;overflow:auto;border:1px solid var(--r);border-radius:9px}.adm-m13-table-wrap table{width:100%;border-collapse:collapse;min-width:660px}.adm-m13-table-wrap th{padding:10px 12px;text-align:left;background:var(--p2);font-size:10px;letter-spacing:.04em}.adm-m13-table-wrap td{padding:11px 12px;vertical-align:top;border-top:1px solid var(--r);color:var(--m);font-size:12px;line-height:1.55}.adm-m13-table-wrap td+td,.adm-m13-table-wrap th+th{border-left:1px solid var(--r)}.adm-m13-check{color:var(--m)}.adm-m13-final{scroll-margin-top:70px;padding:30px 0;border-bottom:1px solid var(--r)}.adm-m13-final h2,.adm-m13-final h4{color:var(--a)}.adm-m13-final code{font:inherit;color:var(--w)}.adm-m13-final a{color:var(--a)}@media(max-width:700px){.adm-m13-book{font-size:13px;line-height:1.68}.adm-m13-table-wrap table{min-width:580px}.adm-m13-session{padding:25px 0}.adm-m13-session-head h3{font-size:22px}.adm-m13-toc{top:4px}}@media(prefers-reduced-motion:reduce){.adm-m13-book *{scroll-behavior:auto!important}}";document.head.appendChild(style);
