function norm(v){var s=String(v||'').toLowerCase();return s.normalize?s.normalize('NFD').replace(/[\u0300-\u036f]/g,''):s;}
function isTarget(s,t){if(!s||s.id!=='adm'||!t)return false;var uid=norm(t.uid),txt=norm((t.title||t.name||t.label||'')+' '+uid);return uid===UID||txt.indexOf('17 contratacao direta')>=0||txt.indexOf('contratacao direta')>=0&&txt.indexOf('adm-17')>=0;}
function install(){if(window.__admM17TheoryInstalledOffline)return true;if(typeof window.renderDetail!=='function')return false;var base=window.renderDetail;window.renderDetail=function(s,t,r){var out=base.apply(this,arguments);if(!isTarget(s,t))return out;if(String(out).indexOf('adm-m17-book')>=0)return out;if(String(out).indexOf(MARKER)>=0)return String(out).replace(MARKER,BOOK_HTML+MARKER);return BOOK_HTML+String(out);};window.__admM17TheoryInstalledOffline=true;try{if(typeof window.renderAll==='function')window.renderAll();}catch(e){console.warn('[ADM M17 offline] renderização',e);}return true;}
