if(!document.getElementById('adm-m17-style-offline')){var style=document.createElement('style');style.id='adm-m17-style-offline';style.textContent=".adm-m17-book{--i:var(--text,#e9eef6);--m:var(--muted,#91a3b9);--r:var(--line,#26364f);--p:var(--panel,#0d1727);--p2:var(--panel2,#111d2f);--a:#93abc9;--w:#d7b879;margin:18px 0 8px;border-top:1px solid var(--r);color:var(--i);font-size:14px;line-height:1.72}.adm-m17-book *{box-sizing:border-box}.adm-m17-book p{margin:9px 0}.adm-m17-book b{font-weight:800}.adm-m17-cover{padding:28px 0 24px;border-bottom:1px solid var(--r)}.adm-m17-kicker{display:flex;justify-content:space-between;gap:12px;color:var(--m);font-size:9px;font-weight:850;letter-spacing:.12em}.adm-m17-type{margin:20px 0 5px!important;color:var(--w);font-size:10px;font-weight:850;letter-spacing:.1em;text-transform:uppercase}.adm-m17-cover h2{max-width:900px;margin:0;font:650 clamp(25px,4vw,38px)/1.08 Georgia,\"Times New Roman\",serif;letter-spacing:-.025em}.adm-m17-sub{max-width:850px;margin:12px 0 0!important;color:var(--m);font:italic 14px/1.55 Georgia,\"Times New Roman\",serif}.adm-m17-source-note{margin-top:18px;padding-top:13px;border-top:1px solid var(--r);color:var(--m);font-size:10px}.adm-m17-toc{position:sticky;top:8px;z-index:4;margin:14px 0 24px;padding:6px;display:flex;gap:4px;overflow:auto;border:1px solid var(--r);border-radius:10px;background:color-mix(in srgb,var(--p) 94%,transparent);backdrop-filter:blur(10px)}.adm-m17-toc a{display:flex;gap:7px;align-items:center;min-width:max-content;padding:8px 9px;border-radius:7px;color:var(--m)!important;text-decoration:none!important;font-size:10px;font-weight:700}.adm-m17-toc a:hover{background:var(--p2);color:var(--i)!important}.adm-m17-toc b{color:var(--w)}.adm-m17-orientacao{margin:0 0 30px;padding:18px 0 20px;border-bottom:1px solid var(--r)}.adm-m17-orientacao h3,.adm-m17-book h1{margin:0 0 10px;font:650 22px/1.2 Georgia,\"Times New Roman\",serif}.adm-m17-flow{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:13px}.adm-m17-flow span{padding:5px 8px;border:1px solid var(--r);border-radius:999px;font-size:9px;font-weight:800;color:var(--m)}.adm-m17-flow i{color:var(--m);font-style:normal}.adm-m17-exam,.adm-m17-callout{margin:16px 0;padding:13px 15px;border-left:3px solid var(--w);background:color-mix(in srgb,var(--p2) 80%,transparent);border-radius:0 8px 8px 0}.adm-m17-session{scroll-margin-top:70px;padding:30px 0;border-bottom:1px solid var(--r)}.adm-m17-session-head{margin-bottom:20px}.adm-m17-session-head small{display:block;margin-bottom:7px;color:var(--w);font-size:9px;font-weight:900;letter-spacing:.14em}.adm-m17-session-head h3{max-width:900px;margin:0;font:650 clamp(22px,3vw,29px)/1.17 Georgia,\"Times New Roman\",serif;letter-spacing:-.015em}.adm-m17-session h4{margin:22px 0 8px;color:var(--a);font-size:11px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.adm-m17-session>p:last-child{margin-top:18px!important;padding:10px 0;border-top:1px dashed var(--r);color:var(--m);font-size:11px}.adm-m17-table-wrap{margin:15px 0;overflow:auto;border:1px solid var(--r);border-radius:9px}.adm-m17-table-wrap table{width:100%;border-collapse:collapse;min-width:650px}.adm-m17-table-wrap th{padding:10px 12px;text-align:left;background:var(--p2);font-size:10px;letter-spacing:.04em}.adm-m17-table-wrap td{padding:11px 12px;vertical-align:top;border-top:1px solid var(--r);color:var(--m);font-size:12px;line-height:1.55}.adm-m17-table-wrap td+td,.adm-m17-table-wrap th+th{border-left:1px solid var(--r)}.adm-m17-master,.adm-m17-fcc,.adm-m17-decorar,.adm-m17-articles,.adm-m17-review,.adm-m17-close{scroll-margin-top:70px;padding:30px 0;border-bottom:1px solid var(--r)}.adm-m17-book ul,.adm-m17-book ol{padding-left:24px}.adm-m17-book li{margin:7px 0}.adm-m17-book hr{border:0;border-top:1px solid var(--r);margin:22px 0}.adm-m17-book code{font-size:.92em}.adm-m17-review{scroll-margin-top:75px}@media(max-width:700px){.adm-m17-book{font-size:13px;line-height:1.68}.adm-m17-table-wrap table{min-width:600px}.adm-m17-session{padding:25px 0}.adm-m17-session-head h3{font-size:22px}.adm-m17-toc{top:4px}}@media(prefers-reduced-motion:reduce){.adm-m17-book *{scroll-behavior:auto!important}}";document.head.appendChild(style);}
